function example() {
  const [hidden, setHidden] = useState(false);
  return (
    <>
      <Button size="small" mb="3" onClick={() => setHidden(h => !h)}>
        {hidden ? 'Show inspector' : 'Hide inspector'}
      </Button>
      <Splitter height={240} className="box p-0">
        <Splitter.Pane label="Canvas">
          <Content p="4">
            <p>The canvas.</p>
          </Content>
        </Splitter.Pane>
        <Splitter.Pane
          label="Inspector"
          defaultSize={35}
          minSize="12rem"
          collapsible
          collapsed={hidden}
          onCollapsedChange={setHidden}
        >
          <Content p="4">
            <p>The inspector.</p>
          </Content>
        </Splitter.Pane>
      </Splitter>
    </>
  );
}

function example() {
  const [sizes, setSizes] = useState([30, 70]);
  return (
    <>
      <Paragraph mb="3">
        {sizes.map(size => `${Math.round(size)}%`).join(' and ')}
      </Paragraph>
      <Splitter
        height={200}
        className="box p-0"
        sizes={sizes}
        onSizesChange={setSizes}
      >
        <Splitter.Pane label="Filters">
          <Content p="4">
            <p>Filters</p>
          </Content>
        </Splitter.Pane>
        <Splitter.Pane label="Results">
          <Content p="4">
            <p>Results</p>
          </Content>
        </Splitter.Pane>
      </Splitter>
    </>
  );
}

